  transition: transform 0.25s;
  flex-shrink: 0;
  line-height: 1;
}
.faq-item.open .faq-icon { transform: rotate(45deg); color: var(--navy); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.25s;
  font-size: 14px;
  color: var(--text-muted);
  line-height: 1.65;
  padding: 0 20px;
}
.faq-item.open .faq-answer {
  max-height: 300px;
  padding: 0 20px 18px;
}

/* ===== TAG PAGES ===== */
.tag-header-section {
  background: var(--navy);
  padding: 36px 24px;
  color: #fff;
}
.tag-header-inner {
  max-width: 1200px;
  margin: 0 auto;
}
.tag-header-section h1 {
  font-size: 32px;
  color: #fff;
  margin-bottom: 6px;
}
.tag-post-count { font-size: 15px; color: rgba(255,255,255,0.6); }

.popular-tags-section {
  background: var(--bg-card);
  border-bottom: 1px solid var(--border);
  padding: 16px 24px;
  overflow-x: auto;
}
.popular-tags-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  gap: 8px;
  align-items: center;
  min-width: max-content;
}
.popular-tag-label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
  flex-shrink: 0;
  margin-right: 4px;
}
.pop-tag-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 12px;
  background: var(--bg);
  border: 1px solid var(--border-dark);
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  transition: all 0.15s;
  white-space: nowrap;
  text-decoration: none;
}
.pop-tag-pill:hover { background: var(--navy); color: #fff; border-color: var(--navy); }
.pop-tag-count { color: var(--text-muted); font-size: 10px; font-weight: 500; }
.pop-tag-pill:hover .pop-tag-count { color: rgba(255,255,255,0.6); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }
  .featured-wrapper { grid-template-columns: 1fr; }
  .featured-thumb { min-height: 200px; }
  .donate-layout { grid-template-columns: 1fr; }
  .two-col-grid { grid-template-columns: 1fr; }
  .challenge-banner { flex-direction: column; text-align: center; }
}

@media (max-width: 768px) {
  .header-search { display: none; }
  .header-nav { display: none; }
  .hamburger { display: flex; }

  .article-grid { grid-template-columns: 1fr; gap: 16px; }
  .featured-title { font-size: 20px; }
  .featured-body { padding: 24px; }

  .section-title { font-size: 19px; }
  .stats-grid { grid-template-columns: 1fr 1fr; }

  .learn-hero h1 { font-size: 26px; }
  .donate-hero h1 { font-size: 28px; }
  .donate-hero p { font-size: 15px; }
  .donate-layout { margin-top: -20px; }

  .tag-header-section h1 { font-size: 24px; }

  .site-footer { margin-top: 48px; }
  .footer-tags { gap: 6px; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .main-content { padding: 32px 0; }
  .stats-grid { grid-template-columns: 1fr; }
  .amount-tabs { gap: 6px; }
  .amount-tab { font-size: 16px; }
}

