  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: #fff;
  flex-shrink: 0;
}
.card-meta-text { font-size: 12px; color: var(--text-muted); }
.card-meta-text strong { color: var(--text); font-weight: 600; }

/* ===== FEATURED ARTICLE ===== */
.featured-wrapper {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
