  flex-direction: column;
  justify-content: center;
}
.featured-eyebrow {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--gold-hover);
  margin-bottom: 12px;
}
.featured-title {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 26px;
  font-weight: 700;
  color: var(--text);
  line-height: 1.3;
  margin-bottom: 20px;
}
.featured-author {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: auto;
}
.featured-author-name { font-size: 14px; font-weight: 600; color: var(--text); }
.featured-author-time { font-size: 12px; color: var(--text-muted); }

/* ===== LOAD MORE ===== */
.load-more-wrap { text-align: center; margin: 8px 0 56px; }
.btn-load-more {
