.btn-load-more:hover { background: var(--navy-light); transform: translateY(-1px); }
.btn-load-more:disabled { opacity: 0.5; cursor: default; transform: none; }

/* ===== FOOTER ===== */
.site-footer {
  background: var(--navy);
  color: rgba(255,255,255,0.7);
  padding: 48px 0 32px;
  margin-top: 80px;
}

.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.footer-mission {
  font-size: 14px;
  line-height: 1.7;
  max-width: 680px;
  margin-bottom: 32px;
  color: rgba(255,255,255,0.65);
}

.footer-section-label {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--gold);
