  padding: 32px 36px;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.challenge-text h3 { font-size: 22px; margin-bottom: 8px; }
.challenge-text p { font-size: 14px; color: rgba(255,255,255,0.7); }
.challenge-links { display: flex; flex-direction: column; gap: 8px; flex-shrink: 0; }
.btn-challenge {
  display: inline-block;
  padding: 10px 20px;
  border-radius: 5px;
  font-size: 13px;
  font-weight: 600;
  text-align: center;
  cursor: pointer;
  transition: opacity 0.2s;
  text-decoration: none;
  white-space: nowrap;
}
.btn-challenge-primary { background: var(--gold); color: var(--navy); }
.btn-challenge-secondary { background: rgba(255,255,255,0.12); color: #fff; border: 1px solid rgba(255,255,255,0.2); }
.btn-challenge:hover { opacity: 0.88; }

/* ===== DONATE PAGE ===== */
.donate-hero {
  background: linear-gradient(135deg, var(--navy) 0%, #1a1a50 100%);
  padding: 64px 24px;
  text-align: center;
  color: #fff;
}
.donate-hero h1 { font-size: 40px; margin-bottom: 16px; color: #fff; }
.donate-hero p {
  font-size: 17px;
  line-height: 1.7;
