}

.donate-layout {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 40px;
  max-width: 1100px;
  margin: -40px auto 0;
  padding: 0 24px;
  position: relative;
  z-index: 10;
}

.donate-main { }

.donate-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  padding: 32px;
  box-shadow: var(--shadow-md);
}

.donate-card h2 {
  font-size: 22px;
  margin-bottom: 24px;
  color: var(--text);
}

.amount-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.amount-tab {
  flex: 1;
  min-width: 60px;
  padding: 14px 8px;
  background: var(--bg);
  border: 2px solid var(--border-dark);
  border-radius: 6px;
  font-family: 'Space Grotesk', sans-serif;
  font-size: 18px;
  font-weight: 700;
  color: var(--text);
  cursor: pointer;
  transition: all 0.18s;
  text-align: center;
}
.amount-tab:hover { border-color: var(--gold); background: #fffbf0; }
.amount-tab.active {
  background: var(--gold);
  border-color: var(--gold);
  color: var(--navy);
  box-shadow: 0 2px 8px rgba(254,172,50,0.35);
}

.donation-description {
  background: #fffbf0;
  border: 1px solid #fde68a;
  border-radius: 6px;
  padding: 14px 18px;
  font-size: 14px;
  color: #78350f;
  margin-bottom: 24px;
  line-height: 1.5;
  font-weight: 500;
  transition: all 0.25s;
}

.btn-donate {
  width: 100%;
  padding: 16px;
  background: var(--gold);
  color: var(--navy);
  font-family: 'Space Grotesk', sans-serif;
  font-size: 18px;
  font-weight: 700;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.2s, transform 0.15s;
  margin-bottom: 12px;
}
.btn-donate:hover { background: var(--gold-hover); transform: translateY(-1px); }

.donate-sublabel {
  text-align: center;
  font-size: 12px;
  color: var(--text-muted);
}
.donate-sublabel a { color: var(--link); text-decoration: underline; }

.secure-badge {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 8px;
  font-size: 12px;
  color: var(--text-muted);
}

.benefits-card {
  background: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  padding: 28px;
  box-shadow: var(--shadow-sm);
}
.benefits-card h3 { font-size: 17px; margin-bottom: 18px; color: var(--text); }
.benefit-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
  font-size: 14px;
}
.benefit-item:last-child { border-bottom: none; }
.benefit-check { color: var(--gold-hover); font-size: 16px; margin-top: 1px; flex-shrink: 0; }

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  margin-bottom: 40px;
}
.stat-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  text-align: center;
}
.stat-number {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 28px;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 4px;
}
.stat-label { font-size: 12px; color: var(--text-muted); line-height: 1.4; }

.initiatives-list { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.initiatives-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 14px;
  color: var(--text);
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
}
.initiatives-list li:last-child { border-bottom: none; }
.initiative-dot {
  width: 8px;
  height: 8px;
  background: var(--gold);
  border-radius: 50%;
  margin-top: 6px;
  flex-shrink: 0;
}

/* ===== FAQ ACCORDION ===== */
.faq-list { display: flex; flex-direction: column; gap: 0; }
.faq-item {
  border-bottom: 1px solid var(--border);
  background: var(--bg-card);
}
.faq-item:first-child { border-radius: var(--radius) var(--radius) 0 0; border-top: 1px solid var(--border); border-left: 1px solid var(--border); border-right: 1px solid var(--border); }
.faq-item:not(:first-child) { border-left: 1px solid var(--border); border-right: 1px solid var(--border); }
.faq-item:last-child { border-radius: 0 0 var(--radius) var(--radius); }

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 20px;
  cursor: pointer;
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  gap: 16px;
  user-select: none;
  transition: background 0.15s;
}
.faq-question:hover { background: var(--bg); }
.faq-icon {
  font-size: 20px;
  color: var(--text-muted);
  transition: transform 0.25s;
  flex-shrink: 0;
  line-height: 1;
}
.faq-item.open .faq-icon { transform: rotate(45deg); color: var(--navy); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.25s;
  font-size: 14px;
  color: var(--text-muted);
  line-height: 1.65;
  padding: 0 20px;
}
.faq-item.open .faq-answer {
  max-height: 300px;
  padding: 0 20px 18px;
}

/* ===== TAG PAGES ===== */
.tag-header-section {
  background: var(--navy);
  padding: 36px 24px;
  color: #fff;
}
.tag-header-inner {
  max-width: 1200px;
  margin: 0 auto;
}
.tag-header-section h1 {
  font-size: 32px;
  color: #fff;
  margin-bottom: 6px;
}
.tag-post-count { font-size: 15px; color: rgba(255,255,255,0.6); }

.popular-tags-section {
  background: var(--bg-card);
  border-bottom: 1px solid var(--border);
  padding: 16px 24px;
  overflow-x: auto;
}
.popular-tags-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  gap: 8px;
  align-items: center;
  min-width: max-content;
}
.popular-tag-label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
  flex-shrink: 0;
  margin-right: 4px;
}
.pop-tag-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 12px;
  background: var(--bg);
  border: 1px solid var(--border-dark);
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  transition: all 0.15s;
  white-space: nowrap;
  text-decoration: none;
}
.pop-tag-pill:hover { background: var(--navy); color: #fff; border-color: var(--navy); }
.pop-tag-count { color: var(--text-muted); font-size: 10px; font-weight: 500; }
.pop-tag-pill:hover .pop-tag-count { color: rgba(255,255,255,0.6); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .article-grid { grid-template-columns: repeat(2, 1fr); }
  .featured-wrapper { grid-template-columns: 1fr; }
  .featured-thumb { min-height: 200px; }
  .donate-layout { grid-template-columns: 1fr; }
  .two-col-grid { grid-template-columns: 1fr; }
  .challenge-banner { flex-direction: column; text-align: center; }
}

@media (max-width: 768px) {
  .header-search { display: none; }
  .header-nav { display: none; }
  .hamburger { display: flex; }

  .article-grid { grid-template-columns: 1fr; gap: 16px; }
  .featured-title { font-size: 20px; }
  .featured-body { padding: 24px; }

  .section-title { font-size: 19px; }
  .stats-grid { grid-template-columns: 1fr 1fr; }

  .learn-hero h1 { font-size: 26px; }
  .donate-hero h1 { font-size: 28px; }
  .donate-hero p { font-size: 15px; }
  .donate-layout { margin-top: -20px; }

  .tag-header-section h1 { font-size: 24px; }

  .site-footer { margin-top: 48px; }
  .footer-tags { gap: 6px; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .main-content { padding: 32px 0; }
  .stats-grid { grid-template-columns: 1fr; }
  .amount-tabs { gap: 6px; }
  .amount-tab { font-size: 16px; }
}
